BEGIN;

-- Limit public gallery uploads to the WebP files generated by the client.
UPDATE storage.buckets
   SET file_size_limit = 5242880,
       allowed_mime_types = ARRAY['image/webp']::text[]
 WHERE id = 'mural-fotos';

-- Accept only identity-folder/timestamp.webp object paths.
DROP POLICY IF EXISTS mural_fotos_storage_insert ON storage.objects;
CREATE POLICY mural_fotos_storage_insert
ON storage.objects
FOR INSERT
TO anon
WITH CHECK (
  bucket_id = 'mural-fotos'
  AND name ~ '^[A-Za-z0-9_-]{1,64}/[0-9]{13}\.webp$'
);

-- Preserve public posting while validating the fields used by the gallery UI.
DROP POLICY IF EXISTS mural_fotos_insert ON public.mural_fotos;
CREATE POLICY mural_fotos_insert
ON public.mural_fotos
FOR INSERT
TO anon
WITH CHECK (
  user_id ~ '^[A-Za-z0-9_-]{1,64}$'
  AND length(btrim(autor_nome)) BETWEEN 1 AND 80
  AND (autor_nivel IS NULL OR length(autor_nivel) <= 40)
  AND (praia IS NULL OR length(praia) <= 80)
  AND (legenda IS NULL OR length(legenda) <= 300)
  AND foto_url ~ '^https://qktabrzbgdfndklytwub\.supabase\.co/storage/v1/object/public/mural-fotos/[A-Za-z0-9_-]{1,64}/[0-9]{13}\.webp$'
);

-- Keep public voting but reject arbitrary identity strings.
DROP POLICY IF EXISTS mural_votos_insert ON public.mural_votos;
CREATE POLICY mural_votos_insert
ON public.mural_votos
FOR INSERT
TO anon
WITH CHECK (user_id ~ '^[A-Za-z0-9_-]{1,64}$');

COMMIT;
